-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.release_fingerprint()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.release_digests_fingerprint(public.release_digests('public'), public.release_digests('draft'));
$function$;

grant execute on function public.release_fingerprint() to service_role;
